// sets payload to different msg variable to
// to persist through http request node
msg.config_variables = msg.payload

msg.headers = {
    "Authorization": "Bearer " + msg.payload.rayvn_api_key
};

msg.url = global.get("rayvn_url") + "/logs";

return msg;

let result = msg.payload;
let name = msg.config_variables.rayvn_log_name;

// Find the log id where the name matches
msg.payload = result.find(item => item.name === name)?.id;
return msg;

let rayvn_config = {
    api_key: msg.config_variables.rayvn_api_key,
    log_name: msg.config_variables.rayvn_log_name,
    log_id: msg.payload
}

global.set("rayvn_config", rayvn_config)
msg.payload = rayvn_config
return msg;

if (
    msg.payload.rayvn_api_key.length > 0 && 
    msg.payload.rayvn_log_name.length > 0
    ) 
    {
        return msg;
    } else {
        node.error("missing rayvn config in msg.payload: ", msg);
        return null
    }

let config = global.get("rayvn_config");
msg.topic = "rayvn_configured"

if (config.api_key &&
    config.log_name &&
    config.log_id) {
        msg.payload = true;
        return msg;
    } else {
        node.error("rayvn config not correctly configured", global.get("rayvn_config"));
        return null;
    }
